create type public.homework_status as enum ('draft','published','closed');
create type public.homework_submission_status as enum ('pending','submitted','graded','late');
create table public.homework (id uuid primary key default gen_random_uuid(),session_id uuid not null references public.class_sessions(id) on delete cascade,title text not null,instructions text not null,due_at timestamptz not null,maximum_score numeric(6,2),status public.homework_status not null default 'draft',created_by uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint homework_title_not_blank check (length(btrim(title)) > 0),constraint homework_title_length_check check (char_length(title) <= 160),constraint homework_instructions_not_blank check (length(btrim(instructions)) > 0),constraint homework_instructions_length_check check (char_length(instructions) <= 4000),constraint homework_maximum_score_check check (maximum_score is null or maximum_score > 0));
create table public.homework_submissions (id uuid primary key default gen_random_uuid(),homework_id uuid not null references public.homework(id) on delete cascade,student_id uuid not null references public.students(id) on delete restrict,status public.homework_submission_status not null default 'pending',submission_text text,submitted_at timestamptz,score numeric(6,2),feedback text,graded_by uuid references public.profiles(id) on delete set null,graded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint homework_submissions_unique_student unique (homework_id, student_id),constraint homework_submission_score_check check (score is null or score >= 0),constraint homework_submission_text_length_check check (submission_text is null or char_length(submission_text) <= 10000),constraint homework_submission_feedback_length_check check (feedback is null or char_length(feedback) <= 4000));
create index homework_session_due_idx on public.homework(session_id,due_at desc);create index homework_status_due_idx on public.homework(status,due_at);create index homework_created_by_idx on public.homework(created_by,created_at desc);create index homework_submissions_homework_status_idx on public.homework_submissions(homework_id,status);create index homework_submissions_student_idx on public.homework_submissions(student_id);
create or replace function private.populate_homework_submissions() returns trigger language plpgsql security definer set search_path='' as $$ declare v_cohort_id uuid; begin if new.status='published'::public.homework_status and (tg_op='INSERT' or old.status is distinct from new.status) then select cohort_id into v_cohort_id from public.class_sessions where id=new.session_id; insert into public.homework_submissions(homework_id,student_id,status) select new.id,cs.student_id,'pending'::public.homework_submission_status from public.cohort_students cs where cs.cohort_id=v_cohort_id and cs.status='active'::public.cohort_membership_status on conflict(homework_id,student_id) do nothing; end if; return new; end; $$;
create trigger homework_populate_submissions after insert or update of status on public.homework for each row execute function private.populate_homework_submissions();
create trigger homework_set_updated_at before update on public.homework for each row execute function private.set_updated_at();create trigger homework_submissions_set_updated_at before update on public.homework_submissions for each row execute function private.set_updated_at();alter table public.homework enable row level security;alter table public.homework_submissions enable row level security;revoke all on public.homework,public.homework_submissions from anon,authenticated;grant all on public.homework,public.homework_submissions to service_role;
